<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { me } from '../api';
import { courseApi, errorText, tag, type Page, type Leave } from '../course-api';
const items=ref<Leave[]>([]), scope=ref<'mine'|'approval'>('mine'), manager=ref(false), page=ref(1), total=ref(0), busy=ref(false), error=ref(''), notice=ref('');
const form=ref({start_date:'',end_date:'',leave_type:'ANNUAL',reason:''}), selected=ref<Leave|null>(null), opinion=ref('');
const types:Record<string,string>={ANNUAL:'年假',SICK:'病假',PERSONAL:'事假',OTHER:'其他'};
const statuses:Record<string,string>={PENDING:'待审批',APPROVED:'已批准',REJECTED:'已驳回',CANCELLED:'已取消'};
async function load(){busy.value=true;error.value='';try{const result=await courseApi<Page<Leave>>(`/leaves?scope=${scope.value}&page=${page.value}&page_size=20`);items.value=result.items;total.value=result.total;selected.value=null;}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function create(){busy.value=true;error.value='';try{await courseApi('/leaves','POST',form.value);notice.value='请假申请已提交';form.value.reason='';scope.value='mine';page.value=1;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function cancel(row:Leave){busy.value=true;error.value='';try{await courseApi(`/leaves/${encodeURIComponent(row.id)}/cancel`,'POST',{},tag(row));notice.value='申请已取消';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function decide(status:'APPROVED'|'REJECTED'){if(!selected.value)return;busy.value=true;error.value='';try{await courseApi(`/leaves/${encodeURIComponent(selected.value.id)}/decision`,'POST',{status,opinion:opinion.value},tag(selected.value));notice.value='审批结果已保存';opinion.value='';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
onMounted(async()=>{try{manager.value=(await me()).roles.includes('MANAGER');await load();}catch(e){error.value=errorText(e);}});
</script>
<template><div class="workspace"><header><span class="brand">HRMS</span><span>请假与审批</span><router-link class="back-link" to="/">返回主页</router-link></header><main><h1>整日请假</h1><p v-if="error" class="error feedback" role="alert">{{error}}</p><p v-if="notice" class="success feedback" role="status">{{notice}}</p>
<section class="card"><h2>申请请假</h2><form @submit.prevent="create"><fieldset :disabled="busy"><div class="form-columns"><label>起始日期<input v-model="form.start_date" type="date" required></label><label>结束日期<input v-model="form.end_date" type="date" required :min="form.start_date"></label><label>类型<select aria-label="类型" v-model="form.leave_type"><option v-for="(label,key) in types" :key="key" :value="key">{{label}}</option></select></label><label>理由<textarea v-model="form.reason" required maxlength="500" rows="3"></textarea></label></div><p class="muted">仅计算工作日；与待审或已批准的工作日重叠将被拒绝。</p><button>提交申请</button></fieldset></form></section>
<section class="card"><div class="section-heading"><h2>{{scope==='mine'?'我的请假记录':'直属部门审批'}}</h2><select v-if="manager" v-model="scope" aria-label="查询范围" @change="page=1;load()"><option value="mine">本人申请</option><option value="approval">直属部门（排除本人）</option></select><button class="secondary" :disabled="busy" @click="load">刷新</button></div><p v-if="busy" role="status">正在加载…</p><p v-else-if="!items.length" class="muted">当前范围暂无请假申请。</p>
<div v-else class="table-scroll"><table><thead><tr><th>员工 / 日期</th><th>类型 / 理由</th><th>状态</th><th>审批留痕</th><th>操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td><small>{{row.employee_id}}</small><br>{{row.start_date}} 至 {{row.end_date}}</td><td>{{types[row.leave_type]}}<br>{{row.reason}}</td><td>{{statuses[row.status]}}</td><td>{{row.opinion||'—'}}<br><small>{{row.decided_at||''}}</small></td><td><button v-if="row.status==='PENDING'&&scope==='mine'" class="text-button" :disabled="busy" @click="cancel(row)">取消申请</button><button v-if="row.status==='PENDING'&&scope==='approval'" class="text-button" :disabled="busy" @click="selected=row;opinion=''">处理审批</button></td></tr></tbody></table></div><nav class="pagination"><span>共 {{total}} 条 · 第 {{page}} 页</span><button :disabled="busy||page<=1" @click="page--;load()">上一页</button><button :disabled="busy||page*20>=total" @click="page++;load()">下一页</button></nav>
<form v-if="selected" class="decision-form" @submit.prevent="decide('APPROVED')"><h3>处理 {{selected.start_date}} 至 {{selected.end_date}} 的申请</h3><label>审批意见<textarea v-model="opinion" required maxlength="500" rows="3"></textarea></label><div class="form-actions"><button :disabled="busy">批准</button><button type="button" class="secondary" :disabled="busy||!opinion.trim()" @click="decide('REJECTED')">驳回</button><button type="button" class="secondary" @click="selected=null">关闭</button></div></form>
</section></main></div></template>
